/* New 3DS entry point for spm3ds.
 *
 * This build runs a recompiled PowerPC program: the synthetic demo generated by
 * tools/make_synthetic.py into source/generated/synthetic.c. It is not the game. The demo
 * loops with lwzu and bdnz, runs a carry chain and a multiply-high, and calls OSReport through
 * the HLE layer. The top screen shows the output, and PASS when the results match the
 * expected values. START exits.
 *
 * UNVERIFIED on hardware: this source has not been compiled against devkitARM, because the
 * toolchain could not be installed in the development environment. */
#include <3ds.h>
#include <stdint.h>
#include <stdio.h>

#include "audio_ndsp.h"
#include "hle.h" /* spm3ds_set_clock, spm3ds_fs_set_root */

int spm3ds_synthetic_run(void); /* generated by tools/make_synthetic.py */
void diag_screen(uint64_t (*now_ns)(void)); /* diag_screen.c: hardware diagnostics */

/* ARM11 system tick rate used by svcGetSystemTick. If libctru's headers define SYSCLOCK_ARM11 we
 * use it. Otherwise this fallback applies. UNVERIFIED: check the value against your installed
 * libctru headers before relying on timing. */
#ifndef SPM3DS_TICK_HZ
#  ifdef SYSCLOCK_ARM11
#    define SPM3DS_TICK_HZ ((uint64_t)SYSCLOCK_ARM11)
#  else
#    define SPM3DS_TICK_HZ ((uint64_t)268123480u)
#  endif
#endif

/* Nanoseconds since boot. The split avoids overflow: ticks * 1e9 does not fit in 64 bits
 * after about 19 seconds of ticks, so we convert whole seconds and the remainder separately. */
static uint64_t now_ns(void) {
    uint64_t ticks = svcGetSystemTick();
    uint64_t seconds = ticks / SPM3DS_TICK_HZ;
    uint64_t rest = ticks % SPM3DS_TICK_HZ;
    return seconds * 1000000000ull + (rest * 1000000000ull) / SPM3DS_TICK_HZ;
}

int main(int argc, char **argv) {
    int ok;
    (void)argc;
    (void)argv;

    gfxInitDefault();
    consoleInit(GFX_TOP, NULL);

    spm3ds_set_clock(now_ns);
    /* Guest files are read from this folder on the SD card, read-only. UNVERIFIED path. */
    spm3ds_fs_set_root("sdmc:/spm3ds/data");
    /* Disc files the user extracted from their own copy of the game (see docs/REQUIRED_FILES.md).
     * The FST is optional: without it, DVD paths map straight to the files directory. */
    spm3ds_dvd_set_root("sdmc:/spm3ds/disc/files");
    if (spm3ds_dvd_load_fst_file("sdmc:/spm3ds/disc/sys/fst.bin") > 0) {
        printf("disc file table loaded\n");
    }

    printf("spm3ds: recompiled PowerPC demo\n");
    ok = spm3ds_synthetic_run();
    printf(ok ? "PASS: translated code ran on the 3DS\n" : "FAIL: results differ\n");
    {
        int audio = spm3ds_audio_init();
        printf(audio ? "Audio: NDSP ready (press X for a test tone)\n"
                     : "Audio: NDSP did not start (is sdmc:/3ds/dspfirm.cdc present?)\n");
    }
    printf("Press Y for hardware diagnostics, START to exit.\n");

    while (aptMainLoop()) {
        static int tone;
        u32 down;
        hidScanInput();
        down = hidKeysDown();
        if (down & KEY_START) {
            break;
        }
        if (down & KEY_Y) {
            diag_screen(now_ns);
        }
        if (down & KEY_X) {
            tone = !tone;
            spm3ds_audio_tone(tone);
            printf("Test tone %s (blocks sent %lu, underruns %lu)\n", tone ? "on" : "off",
                   (unsigned long)spm3ds_audio_blocks(), (unsigned long)spm3ds_audio_underruns());
        }
        spm3ds_audio_pump();
        gfxFlushBuffers();
        gfxSwapBuffers();
        gspWaitForVBlank();
    }

    spm3ds_audio_exit();
    gfxExit();
    return ok ? 0 : 1;
}
